    # Split equal-sized panels with a uniform separator. Equal cells are 3;
    # differing cells get the color shared by the two panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h-r-1:
            a, b = grid[:r], grid[r+1:]
            shared = ({x for row in a for x in row} & {x for row in b for x in row}) - {grid[r][0]}
            bg = next(iter(shared))
            return [[3 if a[i][j] == b[i][j] else bg for j in range(w)] for i in range(r)]
    for c in range(w):
        if all(grid[i][c] == grid[0][c] for i in range(h)) and c == w-c-1:
            a, b = [row[:c] for row in grid], [row[c+1:] for row in grid]
            shared = ({x for row in a for x in row} & {x for row in b for x in row}) - {grid[0][c]}
            bg = next(iter(shared))
            return [[3 if a[i][j] == b[i][j] else bg for j in range(c)] for i in range(h)]
    raise ValueError('no equal panels with a separator')
